class Tree:
    def __init__(self):
        self.parent = {}
        self.children = {}
        self.size = {}
        self.depth = {}
        self.index = 1

    def add_vertex(self, parent):
        child = self.index
        self.parent[child] = parent
        if parent not in self.children:
            self.children[parent] = []
        self.children[parent].append(child)
        self.index += 1
        self.update_sizes(child)
        self.update_depths(child)

    def update_sizes(self, vertex):
        if vertex not in self.children:
            self.size[vertex] = 1
            return
        size = 1
        for child in self.children[vertex]:
            size += self.size[child]
        self.size[vertex] = size

    def update_depths(self, vertex):
        if vertex not in self.children:
            self.depth[vertex] = 0
            return
        max_depth = 0
        for child in self.children[vertex]:
            max_depth = max(max_depth, self.depth[child] + 1)
        self.depth[vertex] = max_depth

    def expected_penalty(self, vertex):
        if vertex not in self.children:
            return 0.0
        total_size = self.size[vertex]
        total_penalty = 0.0
        for child in self.children[vertex]:
            child_size = self.size[child]
            child_penalty = self.expected_penalty(child)
            total_penalty += child_penalty + (child_size / total_size) * (self.depth[child] + 1)
        return total_penalty / total_size

def main():
    q = int(input())
    tree = Tree()
    for _ in range(q):
        query = list(map(int, input().split()))
        if query[0] == 1:
            tree.add_vertex(query[1])
        else:
            print("{:.10f}".format(tree.expected_penalty(query[1])))

if __name__ == "__main__":
    main()
